                selected_observation_id,
                identity_id,
                attribution_basis,
                parent_id,
                unavailable_reason,
                issues,
            ) = match attribution {
                AttributionRow::Selected {
                    selected_funder_id,
                    attribution_basis,
                    selected_parent_declaration_id,
                    issues,
                    ..
                } => {
                    let observation = observations.get(&selected_funder_id).ok_or_else(|| {
                        data_error("attribution references a missing observation")
                    })?;
