            !matches!(row.role.as_str(), "donor" | "payer" | "ultimate_payer")
                || !matches!(row.source_scope.as_str(), "declaration" | "funding_entry")
                || row.funder_id.is_empty()
        }) {
            return Err(data_error("invalid cleaned funder observation"));
        }
