                .iter()
                .find_map(|row| row.name_raw.as_ref().filter(|name| !name.trim().is_empty()));
            let aliases = group
                .iter()
                .filter_map(|row| row.name_raw.as_ref())
                .filter(|name| !name.trim().is_empty())
